class Solution {
    public List<String> buildArray(int[] target,int n){
        List<String> answer=new ArrayList<>();
        int index=0;
        for(int value=1;value<=n&&index<target.length;value++){
            answer.add("Push");
            if(value==target[index])index++;
            else answer.add("Pop");
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun buildArray(target:IntArray,n:Int):List<String>{
        val answer=mutableListOf<String>();
        var index=0;
        for(value in 1..n){
            if(index==target.size)break;
            answer.add("Push");
            if(value==target[index])index++ else answer.add("Pop")
        };
        return answer
    }
}

code.cpp:
class Solution {
    public: vector<string> buildArray(vector<int>& target,int n){
        vector<string> answer;
        int index=0;
        for(int value=1;value<=n&&index<(int)target.size();++value){
            answer.push_back("Push");
            if(value==target[index])++index;
            else answer.push_back("Pop");
        }
        return answer;
    }
};
